sys_variable_value.value:
(function execute(inputs, outputs) {
    var hasRole = false;

    var userRole = new GlideRecord('sys_user_has_role');
    userRole.addQuery('user', inputs.user_sys_id);
    userRole.addQuery('role', '7a3fdb73c3bf5210fc99f3ddd40131bb');
    userRole.query();

    if (userRole.next()) {
        hasRole = true;
    }else{
        hasRole = false;
    }

    outputs.hasRole = hasRole;
})(inputs, outputs);

