sys_variable_value.value:
(function execute(inputs, outputs) {
var hasRole = false;

var userRole = new GlideRecord('sys_user_has_role');
userRole.addQuery('user', inputs.created_by);
userRole.addQuery('role.name', 'STARTSWITH', 'x_1546361_bases.admin - bases');
userRole.query();

if (userRole.next()) {
    hasRole = true;
}

outputs.hasRole = hasRole;


})(inputs, outputs);

